public class InnerBotBuildtimeSettingsFactory(Action<Humidifier.Lex.BotTypes.BuildtimeSettings> factoryAction = null) : SubResourceFactory<Humidifier.Lex.BotTypes.BuildtimeSettings>
{

    internal InnerBotDescriptiveBotBuilderSpecificationFactory DescriptiveBotBuilderSpecificationFactory { get; set; }

    internal InnerBotSampleUtteranceGenerationSpecificationFactory SampleUtteranceGenerationSpecificationFactory { get; set; }

    protected override Humidifier.Lex.BotTypes.BuildtimeSettings Create()
    {
        var buildtimeSettingsResult = CreateBuildtimeSettings();
        factoryAction?.Invoke(buildtimeSettingsResult);

        return buildtimeSettingsResult;
    }

    private Humidifier.Lex.BotTypes.BuildtimeSettings CreateBuildtimeSettings()
    {
        var buildtimeSettingsResult = new Humidifier.Lex.BotTypes.BuildtimeSettings();

        return buildtimeSettingsResult;
    }
    public override void CreateChildren(Humidifier.Lex.BotTypes.BuildtimeSettings result)
    {
        base.CreateChildren(result);

        result.DescriptiveBotBuilderSpecification ??= DescriptiveBotBuilderSpecificationFactory?.Build();
        result.SampleUtteranceGenerationSpecification ??= SampleUtteranceGenerationSpecificationFactory?.Build();
    }

} // End Of Class

